    process.execPath,
    [npmCliCommand, ...args],
    {
        env: { ...process.env, ELECTRON_RUN_AS_NODE: "1" },
        cwd: options.cwd,
        stdio: ['ignore', 'pipe', 'pipe'],
        detached: false
    }
);
```

