 import { EventEmitter } from "events";
 import { AppStatus } from "./main";
 import crypto from "crypto";
 
 // based on @node-red/runtime/lib/exec.js
 
 const child_process = require('child_process');
 const path = require('path');
 
 type RuntimeExec = {
     init: Function;
     run: Function;
 }
 
 let events: EventEmitter;
 let origExec: RuntimeExec;
 let status: AppStatus;
 
 function logLines(id: string, type: string, data: string): void {
     events.emit("event-log", {id:id,payload:{ts: Date.now(),data:data,type:type}});
 }
 
 function resolveNpmCliPath(): string {
-    if (__dirname.includes('app.asar') && process.resourcesPath) {
-        return path.join(process.resourcesPath, "app.asar.unpacked", "node_modules", "npm", "bin", "npm-cli.js");
+    const devPath = path.join(__dirname, "..", "node_modules", "npm", "bin", "npm-cli.js");
+    const fs = require('fs');
+    const asarIdx = __dirname.indexOf(path.sep + 'app.asar' + path.sep);
+    if (asarIdx !== -1) {
+        const resourcesDir = __dirname.substring(0, asarIdx);
+        const unpackedPath = path.join(resourcesDir, "app.asar.unpacked", "node_modules", "npm", "bin", "npm-cli.js");
+        if (fs.existsSync(unpackedPath)) return unpackedPath;
     }
-    return path.join(__dirname, "..", "node_modules", "npm", "bin", "npm-cli.js");
+    return devPath;
 }
 
 const newExec = {
     init: function(_runtime: {events: any, exec: any}, _status: AppStatus) {
         if (!_runtime.exec) {
             throw new Error("runtime.exec not available");
         }
         events = _runtime.events;
         status = _status;
         if (!origExec) {
             origExec = _runtime.exec;
             _runtime.exec = this;
         }
         // Check npm CLI path
         const npmCliPath = resolveNpmCliPath();
         const fs = require('fs');
         if (!fs.existsSync(npmCliPath)) {
             console.warn("Bundled npm CLI not found at", npmCliPath, "- npm operations may fail");
         }
     },
     _run: function(command: string, args: string[], options: any, emit: boolean): Promise<execResult> {
         return origExec.run(command,args,options,emit);
     }, 
     run: function(command: string, args: string[], options: any, emit: boolean): Promise<execResult> {
         if (!command.includes('npm')) {
             return origExec.run(command,args,options,emit);
         }
         var invocationId = crypto.randomUUID();
         const npmCliCommand = resolveNpmCliPath();
 
         emit && events.emit("event-log", {ts: Date.now(),id:invocationId,payload:{ts: Date.now(),data:npmCliCommand+" "+args.join(" ")}});
 
         return new Promise((resolve, reject) => {
             let stdout = "";
             let stderr = "";
 
             const spawnEnv = Object.assign({}, process.env, (options && options.env) || {}, { ELECTRON_RUN_AS_NODE: "1" });
             const child = child_process.spawn(process.execPath, [npmCliCommand, ...args], {
                 cwd: options && options.cwd,
                 env: spawnEnv,
                 stdio: ['ignore', 'pipe', 'pipe'],
                 detached: false
             });
             child.stdout.on('data', (data: any) => {
                 const str = ""+data;
                 stdout += str;
                 emit && logLines(invocationId,"out",str);
             });
             child.stderr.on('data', (data: any) => {
                 const str = ""+data;
                 stderr += str;
                 emit && logLines(invocationId,"err",str);
             });
             child.on('error', function(err: Error) {
                 stderr = err.toString();
                 emit && logLines(invocationId,"err",stderr);
             })
             child.on('close', (code: number) => {
                 let result = {
                     code: code,
                     stdout: stdout,
                     stderr: stderr
                 }
                 emit && events.emit("event-log", {id:invocationId,payload:{ts: Date.now(),data:"rc="+code}});
 
                 if (code === 0) {
                     resolve(result)
                 } else {
                     reject(result);
                 }
             });
         })
     }
 }
 
 export default newExec;

