import { EventEmitter } from "events";
import { AppStatus } from "./main";
import crypto from "crypto";

// based on @node-red/runtime/lib/exec.js

const child_process = require('child_process');
const path = require('path');

type RuntimeExec = {
    init: Function;
    run: Function;
}

let events: EventEmitter;
let origExec: RuntimeExec;
let status: AppStatus;

function logLines(id: string, type: string, data: string): void {
    events.emit("event-log", {id:id,payload:{ts: Date.now(),data:data,type:type}});
}

function resolveNpmCliPath(): string {
    const devPath = path.join(__dirname, "..", "node_modules", "npm", "bin", "npm-cli.js");
    const fs = require('fs');
    if (fs.existsSync(devPath)) return devPath;
    const asarIdx = __dirname.indexOf(path.sep + 'app.asar' + path.sep);
    if (asarIdx !== -1) {
        const resourcesDir = __dirname.substring(0, asarIdx);
        return path.join(resourcesDir, "app.asar", "node_modules", "npm", "bin", "npm-cli.js");
    }
    return devPath;
}

const newExec = {
    init: function(_runtime: {events: any, exec: any}, _status: AppStatus) {
        if (!_runtime.exec) {
            throw new Error("runtime.exec not available");
        }
        events = _runtime.events;
        status = _status;
        if (!origExec) {
